\set ON_ERROR_STOP on
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',false);
insert into storage.objects(bucket_id,name,metadata) values('ai-catalog-documents','10000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000001/file.txt','{"size":12}');
insert into public.catalog_test_state select 'doc',public.ai_catalog_document_save(jsonb_build_object('title','Tài liệu','visibility','team','version_id','20000000-0000-4000-8000-000000000001','filename','Nội dung tiếng Việt.txt','mime_type','text/plain','size_bytes',12,'storage_path','10000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000001/file.txt','checksum',repeat('a',64),'record_id',value->>'id')) from public.catalog_test_state where name='team';
select public.catalog_test_assert(value->'versions'->0->>'filename'='Nội dung tiếng Việt.txt' and not (value::text like '%storage_path%'),'unicode filename and no storage path in document projection') from public.catalog_test_state where name='doc';
insert into storage.objects(bucket_id,name,metadata) values('ai-catalog-documents','10000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000002/file.txt','{"size":15}');
select public.ai_catalog_document_save(jsonb_build_object('title','Tài liệu','visibility','team','document_id',value->>'id','version_id','20000000-0000-4000-8000-000000000002','filename','Bản hai.txt','mime_type','text/plain','size_bytes',15,'storage_path','10000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000002/file.txt','checksum',repeat('b',64))) from public.catalog_test_state where name='doc';
select public.catalog_test_assert(public.ai_catalog_get((value->>'id')::uuid)->'documents'->0->'versions'->0->>'version'='1','attachment remains pinned after new version') from public.catalog_test_state where name='team';
select public.catalog_test_assert(jsonb_array_length(public.ai_catalog_documents()->0->'versions')=2,'document library retains both immutable versions');
select public.catalog_test_assert(public.ai_catalog_document_link((r.value->>'id')::uuid,(d.value->>'id')::uuid,'20000000-0000-4000-8000-000000000002'),'can explicitly repin attachment') from public.catalog_test_state r,public.catalog_test_state d where r.name='team' and d.name='doc';
insert into storage.objects(bucket_id,name,metadata) values('ai-catalog-documents','10000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000003/file.txt','{"size":8}');
insert into public.catalog_test_state select 'private_doc',public.ai_catalog_document_save(jsonb_build_object('title','Riêng','visibility','private','version_id','20000000-0000-4000-8000-000000000003','filename','Riêng.txt','mime_type','text/plain','size_bytes',8,'storage_path','10000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000003/file.txt','checksum',repeat('c',64),'record_id',value->>'id')) from public.catalog_test_state where name='team';
insert into storage.objects(bucket_id,name,metadata) values('ai-catalog-documents','10000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000004/file.txt','{"size":2}');
select public.catalog_test_error('select public.ai_catalog_document_save(''{"title":"Invalid","visibility":"team","version_id":"20000000-0000-4000-8000-000000000004","filename":"Bad.txt","mime_type":"text/plain","size_bytes":3,"storage_path":"10000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000004/file.txt","checksum":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}'')','VALIDATION: size mismatch','object size validated');
delete from storage.objects where name='10000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000004/file.txt';
select public.catalog_test_assert(not exists(select 1 from storage.objects where name like '%000000000004%'),'own orphan cleanup allowed');
with removed as(delete from storage.objects where name like '%000000000001/file.txt' returning *) select public.catalog_test_assert((select count(*) from removed)=0,'registered object cannot be deleted through storage RLS');
select public.catalog_test_error('insert into storage.objects(bucket_id,name) values(''ai-catalog-documents'',''10000000-0000-4000-8000-000000000001/20000000-0000-4000-8000-000000000009/file.txt'')','row-level security','cannot upload to another user prefix');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',false);
select public.catalog_test_assert(jsonb_array_length(public.ai_catalog_documents())=1,'reader does not see private documents');
select public.catalog_test_assert(jsonb_array_length(public.ai_catalog_get((value->>'id')::uuid)->'documents')=1,'team attachment never exposes private document') from public.catalog_test_state where name='team';
select public.catalog_test_assert((select count(*) from storage.objects where bucket_id='ai-catalog-documents')=2,'storage RLS exposes only two team versions');
select public.catalog_test_assert(public.ai_catalog_download('20000000-0000-4000-8000-000000000002')->>'filename'='Bản hai.txt','reader downloads permitted version');
select public.catalog_test_error('select public.ai_catalog_download(''20000000-0000-4000-8000-000000000003'')','NOT_FOUND','reader cannot download private linked document');
select public.catalog_test_error('insert into storage.objects(bucket_id,name) values(''ai-catalog-documents'',''10000000-0000-4000-8000-000000000003/20000000-0000-4000-8000-000000000009/file.txt'')','row-level security','reader cannot upload');
select public.catalog_test_error(format('select public.ai_catalog_document_link(%L,%L)',r.value->>'id',d.value->>'id'),'FORBIDDEN','reader cannot attach documents') from public.catalog_test_state r,public.catalog_test_state d where r.name='team' and d.name='doc';
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',false);
select public.catalog_test_assert((select count(*) from storage.objects where bucket_id='ai-catalog-documents')=0,'nonmember cannot read any storage file');
reset role;
-- Broad old policy simulation proves additive restrictive guards protect only new bucket.
create policy catalog_test_broad_read on storage.objects for select to authenticated,anon using(true);
insert into storage.buckets values('existing-survey','existing-survey',false,null);
insert into storage.objects(bucket_id,name) values('existing-survey','existing-test.txt');
set role authenticated;
select public.catalog_test_assert((select count(*) from storage.objects where bucket_id='ai-catalog-documents')=0,'old permissive policy cannot bypass catalog access');
select public.catalog_test_assert((select count(*) from storage.objects where bucket_id='existing-survey')=1,'existing bucket behavior unchanged');
reset role;
set role anon;
select public.catalog_test_assert((select count(*) from storage.objects where bucket_id='ai-catalog-documents')=0,'anonymous broad policy cannot expose catalog');
reset role;
select public.catalog_test_error('update ai_management.document_versions set filename=''changed''','FORBIDDEN: immutable','version row immutable even through privileged accidental update');
select public.catalog_test_error('delete from storage.objects where bucket_id=''ai-catalog-documents''','FORBIDDEN: registered document object','registered binary guarded from privileged accidental delete');
select public.catalog_test_error('update ai_management.sources set payload=''{}''','FORBIDDEN: immutable','source payload immutable');
select public.catalog_test_error('delete from ai_management.audit','FORBIDDEN: immutable','audit immutable');
select public.catalog_test_assert((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='ai_management' and c.relkind='r' and not c.relrowsecurity)=0,'all catalog tables have RLS');
select public.catalog_test_assert((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'ai_catalog_%' and has_function_privilege('anon',p.oid,'EXECUTE'))=0,'anon lacks every gateway execute privilege');
